void reset_date(void)
{
    settingsdate_state_param_t date_state;
    s32             ret;

    date_state.ampm     = 0;
    date_state.year     = 2024;
    date_state.month    = 5;
    date_state.day      = 13;
    date_state.hour     = 17;
    date_state.min      = 55;
    ret                 = aic_md_write(MD_ID_SETTING_DATE,sizeof(settingsdate_state_param_t),&date_state);

    if (ret) {
        APP_LOGI("reset_date read net cfg error 0x%x\n",ret);
        }
}


