uint8_t get_date_state_ampm()
{
    settingsdate_state_param_t date_state;
    s32             ret;

    ret                 = aic_md_read(MD_ID_SETTING_DATE,sizeof(settingsdate_state_param_t),&date_state);

    if (ret) {
        APP_LOGI("read net cfg error 0x%x\n",ret);
        }

    return date_state.ampm;

}


