/////////////////////////////////////////////////////////////////////////////////
void setting_date_time_value_change_y(uint8_t up_down,lv_obj_t * obj)
{
    uint32_t        child_cnt = lv_obj_get_child_cnt(obj);

    if (up_down) // 向下移动
    {
        lv_obj_t *      temp_obj = lv_obj_get_child(obj,0);
        lv_coord_t      y   = lv_obj_get_y(temp_obj);

        for (uint8_t i = 1; i < child_cnt; i++) {
            lv_obj_t *      temp_obj1 = lv_obj_get_child(obj,i - 1);
            lv_obj_t *      temp_obj2 = lv_obj_get_child(obj,i);
            lv_coord_t      y1  = lv_obj_get_y(temp_obj2);

            lv_obj_set_y(temp_obj1,y1);
            }

        lv_obj_t *      temp_obj3 = lv_obj_get_child(obj,child_cnt - 1);

        lv_obj_set_y(temp_obj3,y);

        }
    else // 向上移动
    {
        lv_obj_t *      temp_obj = lv_obj_get_child(obj,child_cnt - 1);
        lv_coord_t      y   = lv_obj_get_y(temp_obj);

        for (int8_t i = child_cnt - 2; i >= 0; i--) {
            lv_obj_t *      temp_obj1 = lv_obj_get_child(obj,i + 1);
            lv_obj_t *      temp_obj2 = lv_obj_get_child(obj,i);
            lv_coord_t      y1  = lv_obj_get_y(temp_obj2);

            lv_obj_set_y(temp_obj1,y1);
            }

        lv_obj_t *      temp_obj3 = lv_obj_get_child(obj,0);

        lv_obj_set_y(temp_obj3,y);
        }
}


