    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    uint32_t        hour_child_cnt = lv_obj_get_child_cnt(ui_FpSettingsTimeValueHourIndex);
    uint32_t        hour_child_id = get_setting_date_time_value_hour_childId(hour_child_cnt);
    uint32_t        min_child_cnt = lv_obj_get_child_cnt(ui_FpSettingsTimeValueMinIndex);
